// 实际四种业务源与Common cache/history绑定；控制/资格仍为显式隔离读，不冒World或NPC已闭。
#define POLITICAL_SUBORDINATE_RULES_FIXTURE_ONLY
#include "political_subordinate_appointment_rules_test.cpp"
#include "resident/domains/politics/subordinate_appointments/political_subordinate_appointment_receipts.hpp"
namespace {
struct SubordinateReceiptFixture:SubordinateRulesFixture {
 StableId commit(const StableId& actor,const PoliticalSubordinateAppointmentCommand& command,Integer request){auto before=appointed;auto id=submit(actor,command);auto kind=political_subordinate_appointment_command_kind(command);check(take(political_subordinate_appointment_new_player_source(before,appointed,actor,kind,common.tick()))==id,"unique actual four-table source selected");auto r=std::make_shared<CommitResult>();r->ok=true;r->kind=kind;r->tick=common.tick();r->revision=++common.state().identity.revision;r->result_id=take(common.next_id("result"));common.state().request_sequences.set(actor,request);common.state().results.insert(actor+":"+std::to_string(request),r);common.state().history.push_back({r->tick,r->kind,actor,r->result_id,{}});take(bind_political_subordinate_appointment_player_result(common,appointed,id,actor,request,*r,match()));return id;}
 PoliticalSubordinateAppointmentResultMatch match(){return [this](const CommitResult&,const StableId& source,const StableId& office){const auto* a=appointed.arrivals.find(source);return office==(a?a->office_change_fact_id:StableId{});};}
 Status valid(){return validate_political_subordinate_appointment_player_results(common,appointed,match());}
};
}
int main(){try{
 SubordinateReceiptFixture f;auto offer=f.commit("leader",f.offer(),1);auto accepted=f.commit("candidate",PoliticalAnswerSubordinateAppointment{offer,true},1);f.at_county();auto arrived=f.commit("candidate",PoliticalArriveSubordinateAppointment{accepted,0},2);check(f.valid().ok,"actual result after both arrival and original Office head validates");check(f.appointed.arrivals.find(arrived)->player_receipt.has_value(),"arrival retains permanent actual result");auto raw=encode_political_subordinate_appointment_state(f.appointed);auto state=take(decode_political_subordinate_appointment_state(raw));CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);take(visit_political_subordinate_appointment_checkpoint(writer,state));take(writer.finish());const auto& input=bytes;CodecVisitor reader(input);PoliticalSubordinateAppointmentState restored;take(visit_political_subordinate_appointment_checkpoint(reader,restored));take(reader.finish());check(compare_boundary(raw,encode_political_subordinate_appointment_state(restored)).exact(),"four-table binary state retains exact bindings");
 SubordinateReceiptFixture clipped;auto first=clipped.commit("leader",clipped.offer(),1);auto old=clipped.commit("candidate",PoliticalAnswerSubordinateAppointment{first,false},1);auto second=clipped.commit("leader",clipped.offer(),2);auto latest=clipped.commit("candidate",PoliticalAnswerSubordinateAppointment{second,false},2);auto saved=clipped.appointed;auto common=clipped.common.state();auto result=*clipped.common.state().results.find("candidate:2");clipped.common.state().results={};clipped.common.state().results.insert("candidate:2",result);clipped.common.state().history.erase(clipped.common.state().history.begin(),clipped.common.state().history.end()-1);check(clipped.valid().ok,"first remaining history follows permanent actual result");clipped.appointed.answers.erase(latest);clipped.common.state().facts.erase(latest);check(!clipped.valid().ok,"removed latest payload and head cannot relabel old same-tick answer");clipped.common.state()=common;clipped.appointed=saved;clipped.common.state().history.clear();clipped.common.state().results={};check(clipped.valid().ok,"all caches may be pruned without losing actual sources");clipped.appointed.answers.find(latest)->player_receipt.reset();check(!clipped.valid().ok,"empty receipt cannot invent an NPC producer");
 clipped.common.state()=common;clipped.appointed=saved;clipped.appointed.answers.find(latest)->player_receipt.reset();auto copied=*result;check(!bind_political_subordinate_appointment_player_result(clipped.common,clipped.appointed,latest,"candidate",2,copied,clipped.match()).ok,"copied result cannot bind");check(!clipped.appointed.answers.find(latest)->player_receipt,"bad binder leaves no partial write");take(bind_political_subordinate_appointment_player_result(clipped.common,clipped.appointed,latest,"candidate",2,*result,clipped.match()));
 auto before=clipped.appointed;clipped.common.state().metadata.player_actor_id="leader";auto third=clipped.submit("leader",clipped.offer());auto changed=clipped.appointed;changed.offers.find(first)->candidate_actor_id="deputy";check(!political_subordinate_appointment_new_player_source(before,changed,"leader",political_subordinate_offer_command,0).ok,"new source cannot alter old permanent payload");clipped.appointed=before;clipped.common.state()=common;auto withdrawal_offer=clipped.commit("leader",clipped.offer(),3);clipped.commit("leader",PoliticalWithdrawSubordinateAppointment{{"city","chief",0,"leader"},withdrawal_offer},4);check(clipped.valid().ok,"withdrawal receives its own actual result");
 auto invalid=f.appointed;invalid.arrivals.find(arrived)->player_receipt->result_id=f.appointed.arrivals.find(arrived)->office_change_fact_id;check(!validate_political_subordinate_appointment_player_results(f.common,invalid,f.match()).ok,"actual Office fact cannot masquerade as a result");check(!validate_political_subordinate_appointment_player_results(f.common,f.appointed,[](const auto&,const auto&,const auto&){return false;}).ok,"typed effect mismatch rejected");
 std::cout<<checks<<" subordinate receipt checks; typed fixture, not World\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
